<?php session_start(); if(isset($_SESSION['admin'])){header('Location:index.php');exit;} require __DIR__.'/config.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(hash_equals(ADMIN_USER,$_POST['username']??'')&&password_verify($_POST['password']??'',ADMIN_PASS_HASH)){session_regenerate_id(true);$_SESSION['admin']=true;header('Location:index.php');exit;}$error='Incorrect username or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="admin.css"></head><body><main class="login"><section><h2>Admin Login</h2><?php if($error): ?><div class="msg bad"><?=htmlspecialchars($error)?></div><?php endif; ?><form method="post"><label>Username<input name="username" required></label><label>Password<input type="password" name="password" required></label><button>Login</button></form></section></main></body></html>